    parser=argparse.ArgumentParser();parser.add_argument('--pr-url',default='Draft PR 생성 후 기록');args=parser.parse_args()
    r=read(OUT/'RESULT.json');g=read(OUT/'GAP_UPDATE.json');diff=read(OUT/'TRAJECTORY_DIFF.json');grid=read(OUT/'GRID_EFFECT_AUDIT.json');comparison=read(OUT/'UB_COMPARISON.json');full=read(OUT/'BEST_FULL_REPLAY.json');phy=read(OUT/'BEST_CANDIDATE_PHYSICAL_REPLAY.json');raw=read(OUT/'BEST_CANDIDATE_FULL_REPLAY.json');start=read(OUT/'MIP_START_VALIDATION.json');next_action=read(OUT/'NEXT_ACTION_RECOMMENDATION.json');params=read(OUT/'SOLVER_PARAMETERS.json');center=read(OUT/'CENTER_VALIDATION.json')
