    for v in grid['largest_critical_row_improvements_in_binary_block'][:6]:text+=f"| {v['branch_name']} | {v['slot']} | {v['C3A_row']} | {v['required_rho_reduction']} |\n"
    text+='\nPch/Pdis/Q의 affine 기여와 grid 개선은 동반 관찰이며 인과 분해가 아니다. 원래 continuous 변수 전체가 자유로우므로 discrete 시간 block 밖의 grid 변화도 가능하다.\n\n'
    text+=f"다음 행동은 정확히1개: **{next_action['recommendation']}** 이유: {next_action['rationale']} 실행={next_action['executed']}. 이 작업은 여기서 끝나며 다른 solve는 수행하지 않는다.\n\n"
    text+=f"Draft PR: {args.pr_url}\n\n최종40자리 HEAD는 Draft PR 본문의 `Final HEAD`와 사용자 최종 응답에 기록한다. `git rev-parse HEAD`로 확인한다. 동일 commit 파일에 자체 SHA를 넣는 순환을 만들지 않는다. Manifest는 자기 자신과 Python cache를 제외한 namespace 전체 파일의 원본 bytes를 SHA256으로 봉인한다. PR169/170 및 scientific 자료는 기존 hashes와 같아야 하며 최종 작업 트리는 clean이어야 한다.\n"
    (OUT/'FINAL_REVIEW_KO.md').write_text(text,encoding='utf-8')
    verification=read(OUT/'VERIFICATION.json');verification.update(Draft_PR_URL=args.pr_url,manifest_excludes_itself=True,final_HEAD_authority='Published Draft PR body Final HEAD; git rev-parse HEAD; final user response');write('VERIFICATION.json',verification)
    files={str(p.relative_to(OUT)).replace('\\','/'):sha(p) for p in sorted(OUT.rglob('*')) if p.is_file() and p.name!='SHA256_MANIFEST.json' and '__pycache__' not in str(p) and p.suffix!='.pyc'}
    write('SHA256_MANIFEST.json',dict(algorithm='SHA256',scope='All namespace files except manifest itself and Python caches',files=files))
    print('SEALED',len(files),flush=True)
